import pathlib; __file__=str(pathlib.Path(__file__).resolve()); exec(open(pathlib.Path(__file__).parent/'base.py').read())
# Menu repliable et onglets qui défilent (20.2, 11/10/2026) : colonne d'icônes, contenu élargi, choix gardé, nom au survol ;
# Paramètres / Profil : onglets sur une ligne (défilement vers la droite) ; téléphone : menu « burger » inchangé.
ok = lambda c, m: print(('✅ ' if c else '❌ ') + m)
SH = pathlib.Path(os.environ.get('CAPTURES', '/tmp'))
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await ouvrir(b, w=1440); await pg.goto(f'http://localhost:{PORT}/v2.html#accueil'); await pg.wait_for_timeout(2500)
        w0 = await pg.evaluate("document.getElementById('menu').offsetWidth"); z0 = await pg.evaluate("document.getElementById('zone').getBoundingClientRect().left")
        ok(w0 == 252 and z0 == 252, f'menu déplié : 252 px ({w0}, contenu à {z0})')
        pw = await pg.evaluate("document.getElementById('page').getBoundingClientRect().width")
        ok(pw == 1440 - 252, f'pleine largeur (20.1) : la page va du menu au bord droit ({pw} px)')
        await pg.click('#btReplier'); await pg.wait_for_timeout(500)
        w1 = await pg.evaluate("document.getElementById('menu').offsetWidth"); z1 = await pg.evaluate("document.getElementById('zone').getBoundingClientRect().left")
        ok(w1 == 76 and z1 == 76, f'menu replié : 76 px, contenu élargi ({w1}, {z1})')
        ok(await pg.evaluate("document.getElementById('page').getBoundingClientRect().width") == 1440 - 76, 'menu replié : la page prend la place libérée')
        ok(await pg.evaluate("localStorage.getItem('onco360.menuReplie')") == '1' and await pg.get_attribute('#btReplier', 'title') == 'Déplier le menu', 'choix gardé, bouton « Déplier le menu »')
        ok(await pg.evaluate("[...document.querySelectorAll('#menu nav a')].filter(a=>a.offsetParent).every(a=>a.scrollWidth<=a.clientWidth+1)"), 'aucun libellé ne déborde en replié')
        await pg.hover('nav a[data-p="patients"]'); ok(await pg.get_attribute('nav a[data-p="patients"]', 'title') == 'Patients', 'nom de la page au survol')
        await pg.screenshot(path=str(SH / 'menu-replie.png'))
        await pg.reload(); await pg.wait_for_timeout(2500)
        ok(await pg.evaluate("document.body.classList.contains('menu-replie') && document.getElementById('menu').offsetWidth==76"), 'replié après rechargement')
        await pg.click('nav a[data-p="taches"]'); await pg.wait_for_timeout(800)
        ok(await pg.evaluate("location.hash") == '#taches', 'menu replié : clic sur une icône ouvre la page')
        await pg.click('#btReplier'); await pg.wait_for_timeout(500)
        ok(await pg.evaluate("document.getElementById('menu').offsetWidth") == 252 and await pg.evaluate("localStorage.getItem('onco360.menuReplie')") == '0', 'déplié de nouveau (choix gardé)')
        await pg.hover('nav a[data-p="agenda"]'); ok((await pg.get_attribute('nav a[data-p="agenda"]', 'title') or '') == '', 'déplié : pas de bulle (le nom est visible)')
        # Paramètres : onglets sur une ligne
        for larg in (1440, 1100):
            await pg.set_viewport_size({'width': larg, 'height': 900}); await pg.evaluate("location.hash='parametres'"); await pg.wait_for_timeout(1200)
            r = await pg.evaluate("(()=>{const v=document.querySelector('.ag-vues.defile');const bs=[...v.querySelectorAll('button')];return {n:bs.length,top:new Set(bs.map(b=>b.offsetTop)).size,sw:v.scrollWidth,cw:v.clientWidth,page:document.documentElement.scrollWidth,win:innerWidth,cls:v.className}})()")
            ok(r['top'] == 1 and r['page'] <= r['win'], f"Paramètres {larg} px : {r['n']} onglets sur une seule ligne, la page ne déborde pas ({r})")
        await pg.screenshot(path=str(SH / 'parametres-onglets.png'))
        # depuis le 11/10 : 4 familles, elles tiennent sans flèche ; flèches essayées sur une barre rétrécie (même mécanisme)
        ok(not await pg.is_visible('.df-fl.d') and not await pg.is_visible('.df-fl.g'), 'Paramètres : 4 familles, aucune flèche (tout tient)')
        await pg.evaluate("(()=>{const v=document.querySelector('.ag-vues.defile');v.style.maxWidth='230px';v.dispatchEvent(new Event('scroll'));dispatchEvent(new Event('resize'))})()"); await pg.wait_for_timeout(600)
        ok(await pg.is_visible('.df-fl.d') and not await pg.is_visible('.df-fl.g'), 'barre rétrécie : flèche › visible (suite à droite), pas de flèche ‹ au début')
        await pg.click('.df-fl.d'); await pg.wait_for_timeout(700)
        ok(await pg.evaluate("document.querySelector('.ag-vues.defile').scrollLeft") > 0 and await pg.is_visible('.df-fl.g'), 'clic sur › : les onglets défilent, la flèche ‹ apparaît')
        await pg.screenshot(path=str(SH / 'parametres-fleches.png'))
        await pg.evaluate("document.querySelector('.ag-vues.defile').scrollLeft=0"); await pg.wait_for_timeout(500)
        v = '.ag-vues.defile'
        await pg.hover(v); await pg.mouse.wheel(0, 400); await pg.wait_for_timeout(500)
        ok(await pg.evaluate(f"document.querySelector('{v}').scrollLeft") > 0, 'molette : les onglets défilent vers la droite')
        last = await pg.evaluate(f"(()=>{{const bs=document.querySelectorAll('{v} button');return bs.length-1}})()")
        await pg.evaluate(f"document.querySelectorAll('{v} button')[{last}].click()"); await pg.wait_for_timeout(1000)
        r = await pg.evaluate(f"(()=>{{const v=document.querySelector('{v}'),o=v.querySelector('button.on'),a=v.getBoundingClientRect(),c=o.getBoundingClientRect();return c.left>=a.left-1&&c.right<=a.right+1}})()")
        ok(r, 'dernier onglet choisi : visible après le redessin')
        await pg.evaluate("location.hash='profil'"); await pg.wait_for_timeout(1000)
        ok(await pg.evaluate("!!document.querySelector('.ag-vues.defile')"), 'Profil & Paramètres : même barre d\'onglets')
        ok(not pg.errs, 'aucune erreur JavaScript ' + str(pg.errs[:2]))
        # Relief (20.3) : chiffres clés sur une ligne en grand écran, case cliquable qui se soulève au survol
        await pg.set_viewport_size({'width': 1920, 'height': 1000}); await pg.evaluate("location.hash='accueil'"); await pg.wait_for_timeout(1500)
        ok(await pg.evaluate("new Set([...document.querySelectorAll('.kpi .k')].map(k=>k.offsetTop)).size") == 1, '1920 px : les 6 chiffres clés sur une seule ligne')
        await pg.evaluate("document.querySelector('.kpi').scrollIntoView({block:'center'})"); await pg.hover('.kpi .k >> nth=0'); await pg.wait_for_timeout(300)
        ok(await pg.evaluate("getComputedStyle(document.querySelector('.kpi .k')).transform") == 'matrix(1, 0, 0, 1, 0, -2)', 'chiffre clé : se soulève au survol')
        ok(await pg.evaluate("getComputedStyle(document.querySelector('nav a.actif')).boxShadow") != 'none', 'menu actif en relief')
        # Téléphone
        m = await ouvrir(b, w=390, h=844); await m.add_init_script("localStorage.setItem('onco360.menuReplie','1')")
        await m.goto(f'http://localhost:{PORT}/v2.html#parametres'); await m.wait_for_timeout(2500)
        ok(await m.evaluate("getComputedStyle(document.getElementById('btReplier')).display") == 'none' and await m.evaluate("document.getElementById('zone').getBoundingClientRect().left") == 0, 'téléphone : pas de bouton replier, contenu pleine largeur')
        ok(await m.evaluate("document.documentElement.scrollWidth<=innerWidth"), 'téléphone 390 px : rien ne déborde')
        r = await m.evaluate("(()=>{const bs=[...document.querySelectorAll('.ag-vues.defile button')];return new Set(bs.map(b=>b.offsetTop)).size})()")
        ok(r == 1, 'téléphone : onglets des Paramètres sur une ligne')
        await m.click('#burger'); await m.wait_for_timeout(400)
        ok(await m.evaluate("document.getElementById('menu').offsetWidth") == 252 and 'Patients' in await m.inner_text('nav'), 'téléphone : menu « burger » complet (même si replié sur ordinateur)')
        await m.screenshot(path=str(SH / 'menu-telephone.png'))
        ok(not m.errs, 'téléphone : aucune erreur JavaScript')
        await b.close()
asyncio.run(main())
